test('handles large quantities and prices with VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-01-15',
    status: 'draft',
    lines: [{ sku: 'LOGO-PACK', name: 'Logo package', qty: 50, unitPrice: 120000, vatRate: 21, discountPercent: 0 }],
