import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renders a draft invoice with discount and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });

  const result = renderInvoiceText(invoiceResult.value);
  assert.equal(result.ok, true);

  const text = result.value;
  assert.match(text, /^DRAFT\n/);
  assert.match(text, /Northwind Studio\n/);
  assert.match(text, /10 x Design work \(hour\) @ €85\.00 = €850\.00\n/);
  // C-001 is gold tier (5% discount applied automatically)
  assert.match(text, /5% discount: -€42\.50/);
  // Subtotal 850, line discount 42.50, bulk discount 20.19, after discount 787.31, VAT 21% of 787.31 = 165.34
  assert.match(text, /Subtotal: €850\.00/);
  assert.match(text, /VAT: €165\.34/);
  assert.match(text, /Total: €952\.65$/);
});

test('renders an issued invoice with number, discount and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-06-20',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  const result = renderInvoiceText(issuedResult.value);
  assert.equal(result.ok, true);

  const text = result.value;
  assert.match(text, /^INV-2024-0001\n/);
  assert.match(text, /Kite & Co\n/);
  assert.match(text, /5 x Sticker sheet @ €0\.50 = €2\.50\n/);
  // C-003 is silver tier (2.5% discount applied automatically)
  assert.match(text, /2\.5% discount: -€0\.06/);
  // Subtotal 2.50, discount 0.06, after discount 2.44, VAT 21% of 2.44 = 0.5124 ≈ 0.51
  assert.match(text, /Subtotal: €2\.50/);
  assert.match(text, /VAT: €0\.51/);
  assert.match(text, /Total: €2\.95/);
  assert.match(text, /Due: 2024-07-20/);
});

test('renders invoice with multiple lines and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-03-01',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });

  const result = renderInvoiceText(invoiceResult.value);
  assert.equal(result.ok, true);

  const text = result.value;
  assert.match(text, /^DRAFT\n/);
  assert.match(text, /Blue Fern Bakery\n/);
  assert.match(text, /3 x Design work \(hour\) @ €85\.00 = €255\.00/);
  assert.match(text, /2 x Copywriting \(hour\) @ €60\.00 = €120\.00/);
  // C-002 is standard tier (0% discount)
  // Subtotal: 255 + 120 = 375
  // VAT: 375 * 21% = 78.75
  assert.match(text, /Subtotal: €375\.00/);
  assert.match(text, /VAT: €78\.75/);
  assert.match(text, /Total: €453\.75$/);
});

test('renders invoice with line discount and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  });

  const result = renderInvoiceText(invoiceResult.value);
  assert.equal(result.ok, true);

  const text = result.value;
  assert.match(text, /10 x Design work \(hour\) @ €85\.00 = €850\.00/);
  assert.match(text, /10% discount: -€85\.00/);
  // Line discount: 85 (10%), Bulk discount: 19.12 (2.5% of 765), After discount: 745.88, VAT: 745.88 * 21% = 156.63
  assert.match(text, /Subtotal: €850\.00/);
  assert.match(text, /Discount: -€104\.12/);
  assert.match(text, /VAT: €156\.63/);
  assert.match(text, /Total: €902\.51$/);
});

test('renders invoice with multiple line discounts and VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'STICKER', qty: 100, discountPercent: 20 },
    ],
  });

  const result = renderInvoiceText(invoiceResult.value);
  assert.equal(result.ok, true);

  const text = result.value;
  assert.match(text, /10 x Design work \(hour\) @ €85\.00 = €850\.00/);
  assert.match(text, /10% discount: -€85\.00/);
  assert.match(text, /100 x Sticker sheet @ €0\.50 = €50\.00/);
  assert.match(text, /20% discount: -€10\.00/);
  // DES-HOUR: line disc 85, bulk disc 19.12, after discount 745.88, VAT: 156.63
  // STICKER: line disc 10, bulk disc 1, after discount 39, VAT: 8.19
  // Total VAT: 156.63 + 8.19 = 164.82
  assert.match(text, /Subtotal: €900\.00/);
  assert.match(text, /Discount: -€115\.12/);
  assert.match(text, /VAT: €164\.82/);
  assert.match(text, /Total: €949\.70$/);
});

test('shows subtotal/vat lines when VAT is present', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });

  const result = renderInvoiceText(invoiceResult.value);
  assert.equal(result.ok, true);

  const text = result.value;
  // With explicit 0 discount, no discount line, but VAT should show
  assert.match(text, /Subtotal: €425\.00/);
  assert.doesNotMatch(text, /Discount:/);
  assert.match(text, /VAT: €89\.25/);
  assert.match(text, /Total: €514\.25$/);
});

test('formats all amounts through formatEuros with VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  const result = renderInvoiceText(invoiceResult.value);
  assert.equal(result.ok, true);

  const text = result.value;
  // PRINT-A4: 37 cents per unit, 100 units = 3700 cents = €37.00 (9% VAT)
  assert.match(text, /100 x Printed flyer A4 \(each\) @ €0\.37 = €37\.00/);
  // WORKSHOP-DAY: 60000 cents = €600.00 (0% VAT)
  assert.match(text, /1 x Brand workshop \(day, VAT exempt\) @ €600\.00 = €600\.00/);
  // C-001 is gold tier (5% discount)
  // PRINT-A4: qty 100, line discount €1.85, bulk discount €0.88, total €2.73 discount, VAT: €3.08
  // WORKSHOP-DAY: qty 1, line discount €30.00, no bulk, VAT: €0
  // Total subtotal: €637.00, discount: €32.73, vat: €3.08
  // Total: €637.00 - €32.73 + €3.08 = €607.35
  assert.match(text, /Total: €607\.35$/);
});

